// Candidate: glibc atoi == (int)strtol(s, NULL, 10)
fn c_atoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    // C locale isspace: ' ', \t(0x09), \n(0x0a), \v(0x0b), \f(0x0c), \r(0x0d)
    while i < bytes.len() && matches!(bytes[i], b' ' | 0x09 | 0x0a | 0x0b | 0x0c | 0x0d) {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let mut acc: i64 = 0;
    let mut sat = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let d = (bytes[i] - b'0') as i64;
        if !sat {
            match acc.checked_mul(10).and_then(|v| v.checked_add(d)) {
                Some(v) => acc = v,
                None => { sat = true; }
            }
        }
        i += 1;
    }
    let val: i64 = if sat {
        if neg { i64::MIN } else { i64::MAX }
    } else if neg {
        // magnitude accumulated positively; negate. acc <= i64::MAX so safe.
        -acc
    } else {
        acc
    };
    val as i32
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    if args.len() < 2 { println!("noargs"); return; }
    use std::os::unix::ffi::OsStrExt;
    println!("{}", c_atoi(args[1].as_bytes()));
}
EOF
rustc -O -o /tmp/probe/rs/cand /tmp/probe/rs/cand.rs 2>&1 | head -20 && echo BUILT_OK

