#include <stdio.h>
#include <stdlib.h>
// emit hex-encoded random-ish inputs, one per line
static const char *alpha = "0123456789 \t\n\v\f\r+-.eExXabcABC_,";
int main(int argc,char**argv){
    unsigned long seed = 12345; if(argc>1) seed=strtoul(argv[1],0,10);
    srandom(seed);
    int N = 200000;
    for(int k=0;k<N;k++){
        int len = random()%14;           // 0..13
        // bias: sometimes long digit runs
        if(k%7==0) len = 15 + random()%12;
        unsigned char buf[64]; int L=0;
        for(int j=0;j<len;j++){
            unsigned char c;
            int r = random()%100;
            if(r<55) c = '0' + random()%10;
            else if(r<70) c = alpha[random()%31];
            else c = (unsigned char)(random()%255 + 1); // any nonzero byte
            buf[L++]=c;
        }
        for(int j=0;j<L;j++) printf("%02x", buf[j]);
        printf("\n");
    }
    return 0;
}
EOF
