int main(void){
    char line[4096];
    while(fgets(line,sizeof line,stdin)){
        size_t n=strlen(line); while(n&&(line[n-1]=='\n'||line[n-1]=='\r')) line[--n]=0;
        unsigned char buf[2048]; size_t L=0;
        for(size_t i=0;i+1<n;i+=2){ buf[L++]=(unsigned char)(hexv(line[i])*16+hexv(line[i+1])); }
        buf[L]=0;
        printf("%d\n", atoi((char*)buf));
    }
    return 0;
}
EOF
