use std::io::{self, Read, Write};
fn c_atoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    while i < bytes.len() && matches!(bytes[i], b' ' | 0x09 | 0x0a | 0x0b | 0x0c | 0x0d) { i += 1; }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') { neg = bytes[i] == b'-'; i += 1; }
    let mut acc: i64 = 0; let mut sat = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let d = (bytes[i] - b'0') as i64;
        if !sat {
            match acc.checked_mul(10).and_then(|v| v.checked_add(d)) { Some(v)=>acc=v, None=>{sat=true;} }
        }
        i += 1;
    }
    let val: i64 = if sat { if neg { i64::MIN } else { i64::MAX } } else if neg { -acc } else { acc };
    val as i32
}
fn hexv(c: u8) -> i32 { match c { b'0'..=b'9' => (c-b'0') as i32, b'a'..=b'f' => (c-b'a'+10) as i32, b'A'..=b'F'=>(c-b'A'+10) as i32, _=>-1 } }
fn main(){
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let out = io::stdout(); let mut w = io::BufWriter::new(out.lock());
    for line in s.lines() {
        let h = line.trim_end();
        let hb = h.as_bytes();
        let mut buf: Vec<u8> = Vec::with_capacity(hb.len()/2);
        let mut i = 0; while i+1 < hb.len() { buf.push((hexv(hb[i])*16 + hexv(hb[i+1])) as u8); i+=2; }
        writeln!(w, "{}", c_atoi(&buf)).unwrap();
    }
}
EOF
